    parts = re.split(r"[ \t]+", text)
    if len(parts) != 5:
        raise ValueError(f"expected 5 fields, got {len(parts)}: {expr!r}")
    minute, hour, dom, month, dow = parts
    fields = [
        _parse_field(minute, "minute"),
        _parse_field(hour, "hour"),
        _parse_field(dom, "dom"),
        _parse_field(month, "month"),
        _parse_field(dow, "dow"),
    ]
    if fields[0].last or fields[1].last or fields[3].last or fields[4].specials and False:
        raise ValueError(f"L not allowed here: {expr!r}")
    if fields[0].specials or fields[1].specials or fields[2].specials or fields[3].specials:
        raise ValueError(f"bad field in {expr!r}")
    return _Spec(fields[0].values, fields[1].values, fields[2], fields[3].values, fields[4])


def _spec(expr):
    if not isinstance(expr, str):
        raise ValueError(f"expression must be a string: {expr!r}")
    return _parse(expr)


def _day_ok(spec, year, month, day, dim):
    """True if the day matches both the day-of-month and the day-of-week fields."""
    dom = spec.dom
    if not (day in dom.values or (dom.last and day == dim)):
        return False
    weekday = _dt.date(year, month, day).isoweekday() % 7  # Sunday is 0
    if weekday in spec.dow.values:
        return True
    for special in spec.dow.specials:
        if special[0] == "last":
            if special[1] % 7 == weekday and day + 7 > dim:
                return True
        else:
            _, n, k = special
            if n % 7 == weekday and (day - 1) // 7 + 1 == k:
                return True
    return False


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    spec = _spec(expr)
    if when.minute not in spec.minutes or when.hour not in spec.hours or when.month not in spec.months:
        return False
    dim = calendar.monthrange(when.year, when.month)[1]
    return _day_ok(spec, when.year, when.month, when.day, dim)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    spec = _spec(expr)
    try:
        start = after.replace(second=0, microsecond=0) + _dt.timedelta(minutes=1)
        limit = after + _dt.timedelta(days=50 * 365)
    except OverflowError:
        return None
    hours = sorted(spec.hours)
    minutes = sorted(spec.minutes)
    year, month = start.year, start.month
    while (year, month) <= (limit.year, limit.month):
        if month in spec.months:
            dim = calendar.monthrange(year, month)[1]
            first_day = start.day if (year, month) == (start.year, start.month) else 1
            for day in range(first_day, dim + 1):
                if not _day_ok(spec, year, month, day, dim):
                    continue
                for hour in hours:
                    for minute in minutes:
                        candidate = _dt.datetime(year, month, day, hour, minute)
                        if candidate < start:
                            continue
                        if candidate > limit:
                            return None
                        return candidate
        month += 1
        if month > 12:
            month = 1
            year += 1
    return None
